                        r"Ответчик[:\s][\s\S]{1,500}?ИНН[:\s]*([0-9]{10,12})",  # ПРИОРИТЕТ: ИНН в блоке Ответчик (для ЮЛ)
                        r"Должник[:\s][\s\S]{0,500}?ИНН[:\s]*([0-9]{10,12})(?=[\s\S]{0,500}?(?:Истец|кредитор|$))",  # ИНН в блоке должника до блока Истец
                        r"Должник[:\s][\s\S]{1,200}?ИНН[:\s]*([0-9]{10,12})",  # приоритет: ИНН в блоке должника
                        r"должник[:\s][\s\S]{1,200}?ИНН[:\s]*([0-9]{10,12})",
                        r"(?:ООО|ОАО|ПАО|ЗАО|АО|Обществ[ао]\s+с\s+ограниченной\s+ответственностью|Публичное\s+акционерное\s+общество)[^,\n]{0,200}?ИНН[:\s]*([0-9]{10,12})(?=[\s\S]{0,500}?(?:Истец|$))",  # ИНН после названия организации до Истец
                        r"(?:ООО|ОАО|ПАО|ЗАО|АО|Обществ[ао]\s+с\s+ограниченной\s+ответственностью|Публичное\s+акционерное\s+общество)[^,\n]{0,200}?ИНН[:\s]*([0-9]{10,12})",  # ИНН после названия организации
                        r"ООО\s*«?[^\n]+»?\s*,?\s*ИНН[:\s]*([0-9]{10,12})",
