                        r"Должник[:\s][\s\S]{0,500}?ОГРН[:\s]*([0-9]{12,15})(?=[\s\S]{0,500}?(?:Истец|кредитор|$))",  # ОГРН в блоке должника до блока Истец (12-15 цифр)
