                        r"\[4\.1\]\s*([0-9]{12,15})",  # [4.1] ОГРНИП
                        r"([0-9]{12,15})\s*\[4\.1\]",  # ОГРНИП [4.1]
                        r"Ответчик[:\s][\s\S]{0,1000}?ОГРНИП[:\s]*([0-9]{12,15})(?=[\s\S]{0,500}?(?:Истец|Представитель|ПРОСИМ|ПРИЛОЖЕНИЯ|$))",  # ОГРНИП в блоке Ответчик
                        r"Должник[:\s][\s\S]{0,500}?ОГРНИП[:\s]*([0-9]{12,15})(?=[\s\S]{0,500}?(?:Истец|кредитор|$))",  # ОГРНИП в блоке должника
                        r"ИП[:\s][\s\S]{0,200}?ОГРНИП[:\s]*([0-9]{12,15})",  # ОГРНИП после ИП
