                        # (город/улица могут начинаться с "г." / "ул." и т.п., а не с заглавной буквы)
                        r"должник[:\s][\s\S]{0,500}?(?:место\s+жительства|адрес\s+регистрации|адрес)[:\s]*([0-9]{6}[,\s]+[^,\n]+(?:[,\s]+[^,\n]+)*?)(?:\n|$|[,\[]|(?:телефон|дата|огрн|инн|снилс|паспорт|серия|номер|ИНН|ОГРН))",
