                        r"\[6\]\s*([0-9]{6}[,\s]+[^,\n]+(?:[,\s]+[^,\n]+)*?)(?:\n|$|[,\[]|(?:телефон|дата|огрн|инн|снилс|паспорт|серия|номер))",  # [6] Адрес регистрации (многочастный)
                        r"место\s+жительства[:\s]*([0-9]{6}[,\s]+[^,\n]+(?:[,\s]+[^,\n]+)*?)(?:\n|$|[,\[]|(?:телефон|дата|огрн|инн|снилс|паспорт|серия|номер|договор|далее|путем|подписания|клиентом|индивидуальных|условий|потребительского|кредита))",  # место жительства: адрес
                        r"адрес\s+регистрации[:\s]*([0-9]{6}[,\s]+[^,\n]+(?:[,\s]+[^,\n]+)*?)(?:\n|$|[,\[]|(?:телефон|дата|огрн|инн|снилс|паспорт|серия|номер|договор|далее|путем|подписания|клиентом|индивидуальных|условий|потребительского|кредита))",  # адрес регистрации: адрес
                        r"место\s+жительства[:\s]*([0-9]{6}[,\s]+[^,\n]+(?:[,\s]+[^,\n]+)*?)(?:\n|$|[,\[]|(?:телефон|дата|огрн|инн|снилс|паспорт|серия|номер|договор|далее|путем|подписания|клиентом|индивидуальных|условий|потребительского|кредита))",  # место жительства: полный адрес
                        r"адрес\s+регистрации[:\s]*([0-9]{6}[,\s]+[^,\n]+(?:[,\s]+[^,\n]+)*?)(?:\n|$|[,\[]|(?:телефон|дата|огрн|инн|снилс|паспорт|серия|номер|договор|далее|путем|подписания|клиентом|индивидуальных|условий|потребительского|кредита))",  # адрес регистрации: полный адрес с городом, улицей, домом
                        r"место\s+жительства[:\s]*([0-9]{6}[,\s]+[^,\n]+(?:[,\s]+[^,\n]+)*?)(?:\n|$|[,\[]|(?:телефон|дата|огрн|инн|снилс|паспорт|серия|номер|договор|далее|путем|подписания|клиентом|индивидуальных|условий|потребительского|кредита))",  # место жительства: полный адрес с городом, улицей, домом
                        r"ЗУБЕНКО\s+МИХАИЛ\s+ПЕТРОВИЧ[^,\n]*?([0-9]{6}[,\s]+[^,\n]+(?:[,\s]+[^,\n]+)*?)(?:\n|$|[,\[]|(?:телефон|дата|огрн|инн|снилс|паспорт|серия|номер|договор|далее|путем|подписания|клиентом|индивидуальных|условий|потребительского|кредита))",  # Адрес после ФИО с русскими буквами
                        r"ЗУБЕНКО\s+МИХАИЛ\s+ПЕТРОВИЧ[^,\n]*?([0-9]{6}[,\s]+[^,\n]+(?:[,\s]+[^,\n]+)*?)(?:\n|$|[,\[]|(?:телефон|дата|огрн|инн|снилс|паспорт|серия|номер|договор|далее|путем|подписания|клиентом|индивидуальных|условий|потребительского|кредита))",  # Адрес после полного ФИО ЗУБЕНКО (исключая договоры)
                        r"ЗУБЕНКО[^,\n]*?([0-9]{6}[,\s]+[^,\n]+(?:[,\s]+[^,\n]+)*?)(?:\n|$|[,\[]|(?:телефон|дата|огрн|инн|снилс|паспорт|серия|номер|банкрот|процедур|реализац|имуществ|опубликов|сайт|Единого|федерального|реестр|сведений|банкротств|родительный|падеж|\[2\]|\[9\]|договор|далее|путем|подписания|клиентом|индивидуальных|условий|потребительского|кредита))",  # Адрес после ФИО ЗУБЕНКО (без [9] и договоров)
