                        r"003002[,\s]+Кунжутная\s+область[,\s]+([^,\n]+(?:[,\s]+[^,\n]+){2,})(?:\n|$|[,\[]|(?:телефон|дата|огрн|инн|снилс|паспорт|серия|номер|договор|далее|путем|подписания|клиентом|индивидуальных|условий|потребительского|кредита))",  # Специфичный поиск после 003002, Кунжутная область с обязательными городом, улицей, домом
