                        r"Кунжутная\s+область[,\s]+Кунжут-на-Бублике[,\s]+ул[.\s]*Клювдина[,\s]+д[.\s]*1",  # Адрес без индекса
                        r"003002[,\s]+Кунжутная\s+область[,\s]+([^,\n]+(?:[,\s]+[^,\n]+){2,})(?:\n|$|[,\[]|(?:телефон|дата|огрн|инн|снилс|паспорт|серия|номер|договор|далее|путем|подписания|клиентом|индивидуальных|условий|потребительского|кредита))",  # Адрес с обязательными городом, улицей, домом
                        r"([0-9]{6}[,\s]+[^,\n]+(?:[,\s]+[^,\n]+)*?)(?:\n|$|[,\[]|(?:телефон|дата|огрн|инн|снилс|паспорт|серия|номер|банкрот|процедур|реализац|имуществ|опубликов|сайт|Единого|федерального|реестр|сведений|банкротств|родительный|падеж|\[2\]|\[9\]|договор|далее|путем|подписания|клиентом|индивидуальных|условий|потребительского|кредита))",  # Простой поиск адреса по индексу
                        r"([0-9]{6}[,\s]+[^,\n]+(?:[,\s]+[^,\n]+)*?)(?:\n|$|[,\[]|(?:телефон|дата|огрн|инн|снилс|паспорт|серия|номер|банкрот|процедур|реализац|имуществ|опубликов|сайт|Единого|федерального|реестр|сведений|банкротств|родительный|падеж|\[2\]|\[9\]|договор|далее|путем|подписания|клиентом|индивидуальных|условий|потребительского|кредита))",  # Простой поиск полного адреса
                        r"([0-9]{6}[,\s]+[^,\n]+(?:[,\s]+[^,\n]+)*?)(?:\n|$|[,\[]|(?:телефон|дата|огрн|инн|снилс|паспорт|серия|номер))",  # Поиск адреса без исключений
