                        r"заявитель[^,\n]*?адрес\s+регистрации[:\s]+([0-9]{6}[,\s]+[^,\n]+(?:[,\s]+[^,\n]+)*?)(?:\n|$|[,\[]|(?:телефон|дата|огрн|инн|снилс|паспорт|серия|номер))",  # Адрес регистрации заявителя (многочастный)
                        r"должник[^,\n]*?проживает[:\s]+([0-9]{6}[,\s]+[^,\n]+(?:[,\s]+[^,\n]+)*?)(?:\n|$|[,\[]|(?:телефон|дата|огрн|инн|снилс|паспорт|серия|номер))",  # Должник проживает (многочастный)
                        r"заявитель[^,\n]*?проживает[:\s]+([0-9]{6}[,\s]+[^,\n]+(?:[,\s]+[^,\n]+)*?)(?:\n|$|[,\[]|(?:телефон|дата|огрн|инн|снилс|паспорт|серия|номер))",  # Заявитель проживает (многочастный)
                        r"должник[^,\n]*?адрес[:\s]+([0-9]{6}[,\s]+[^,\n]+(?:[,\s]+[^,\n]+)*?)(?:\n|$|[,\[]|(?:телефон|дата|огрн|инн|снилс|паспорт|серия|номер))",  # Адрес должника (многочастный)
                        r"заявитель[^,\n]*?адрес[:\s]+([0-9]{6}[,\s]+[^,\n]+(?:[,\s]+[^,\n]+)*?)(?:\n|$|[,\[]|(?:телефон|дата|огрн|инн|снилс|паспорт|серия|номер))",  # Адрес заявителя (многочастный)
