                        r"должник[^,\n]*?([0-9]{6}[,\s]+[^,\n]+(?:[,\s]+[^,\n]+)*?)(?:\n|$|[,\[]|(?:телефон|дата|огрн|инн|снилс|паспорт|серия|номер))",  # Любой адрес после "должник" (многочастный)
                        r"заявитель[^,\n]*?([0-9]{6}[,\s]+[^,\n]+(?:[,\s]+[^,\n]+)*?)(?:\n|$|[,\[]|(?:телефон|дата|огрн|инн|снилс|паспорт|серия|номер))",  # Любой адрес после "заявитель" (многочастный)
