                        r"(Арбитражный\s+суд[А-ЯЁа-яё\s]+(?:области|края|республики|города|автономного\s+округа|автономной\s+области)[А-ЯЁа-яё\s]*)",  # Арбитражный суд ... (полное название)
                        r"([А-ЯЁ][А-ЯЁа-яё\s]+арбитражный\s+суд[А-ЯЁа-яё\s]+(?:области|края|республики|города|автономного\s+округа|автономной\s+области)[А-ЯЁа-яё\s]+)(?=\s*\n\s*[0-9]{5,6})",  # Полное название до адреса с переносом строки
                        r"([А-ЯЁ][А-ЯЁа-яё\s]+арбитражный\s+суд[А-ЯЁа-яё\s]+(?:области|края|республики|города|автономного\s+округа|автономной\s+области)[А-ЯЁа-яё\s]+)(?=\s+[0-9]{5,6}|$|\n|,|\.)",  # Полное название до адреса
                        r"([А-ЯЁ][А-ЯЁа-яё\s]+арбитражный\s+суд[А-ЯЁа-яё\s]+(?:области|края|республики|города|автономного\s+округа|автономной\s+области)[А-ЯЁа-яё\s]*)",  # Полное название
