                        r"([А-ЯЁ][^,\n]*?арбитражный\s+суд[^,\n]*?(?:области|края|республики|города|автономного\s+округа|автономной\s+области)[^,\n]*?)(?=\s+[0-9]{5,6}|$|\n|,|\.)",  # Полное название с регионом до адреса
                        r"в\s+([А-ЯЁ][^,\n]*?арбитражный\s+суд[^,\n]*?(?:области|края|республики|города|автономного\s+округа|автономной\s+области)[^,\n]*?)(?=\s+[0-9]{5,6}|$|\n|,|\.)",  # в ... арбитражный суд ... до адреса
