                        r"договор\s+поручительства\s+от\s+(\d{1,2}[.,]\d{1,2}[.,]\d{4})\s+№\s+[0-9А-ЯЁa-z/\-]+",
                        r"заключили\s+кредитный\s+договор\s+от\s+(\d{1,2}[.,]\d{1,2}[.,]\d{4})",
