                        r"финансовый\s+управляющий[:\s]+([А-ЯЁ][а-яёА-ЯЁ\s]+?)(?:\n|Адрес|адрес|ИНН|СНИЛС|Телефон|Дата|\(|$)",  # ФИО до новой строки или "Адрес"
                        r"управляющий[:\s]+([А-ЯЁ][а-яёА-ЯЁ\s]+?)(?:\n|Адрес|адрес|ИНН|СНИЛС|Телефон|Дата|\(|$)",
                        r"утвердить[^,]*?([А-ЯЁ][а-яёА-ЯЁ\s]+?)\s+финансовым",
                        r"финансовым\s+управляющим[:\s]+([А-ЯЁ][а-яёА-ЯЁ\s]+?)(?:\n|Адрес|адрес|ИНН|СНИЛС|Телефон|Дата|\(|$)",
                        r"([А-ЯЁ][а-яёА-ЯЁ\s]+?)\s+финансовый\s+управляющий",
