                        r"конкурсный\s+управляющий[:\s]+([А-ЯЁ][а-яёА-ЯЁ\s]+?)(?:\n|Адрес|адрес|ИНН|СНИЛС|Телефон|Дата|\(|$)",
                        r"конкурсным\s+управляющим[:\s]+([А-ЯЁ][а-яёА-ЯЁ\s]+?)(?:\n|Адрес|адрес|ИНН|СНИЛС|Телефон|Дата|\(|$)",
