                        r"третье\s+лицо[^,\n]*?адрес\s+регистрации[:\s]+([0-9]{6}[,\s]+[^,\n]+(?:[,\s]+[^,\n]+)*?)(?:\n|$|[,\[]|(?:телефон|дата|огрн|инн|снилс|паспорт|серия|номер))",  # Адрес регистрации третьего лица (многочастный)
                        r"поручитель[^,\n]*?адрес\s+регистрации[:\s]+([0-9]{6}[,\s]+[^,\n]+(?:[,\s]+[^,\n]+)*?)(?:\n|$|[,\[]|(?:телефон|дата|огрн|инн|снилс|паспорт|серия|номер))",  # Адрес регистрации поручителя (многочастный)
