                        r"гарант[^,\n]*?адрес[:\s]+([0-9]{6}[,\s]+[^,\n]+(?:[,\s]+[^,\n]+)*?)(?:\n|$|[,\[]|(?:телефон|дата|огрн|инн|снилс|паспорт|серия|номер))",  # Адрес гаранта (многочастный)
